from pathlib import Path
import json,itertools,collections
P=Path(__file__).resolve().parent
src=json.loads((P.parent/'words.json').read_text())['words'];by={x['word']:x for x in src}
old=json.loads((P.parent/'central-concepts/classification.json').read_text())
old_centers=['эмоция','чувство','переживание','настроение','ощущение'];new=['состояние','отношение','реакция','выражение','желание']
# Identical comparison universe for ten centers: exclude the six source words that are centers.
universe=set(by)-set(old_centers)-{'желание'}
assert len(universe)==304
canon={w:w for w in by}
for g in json.loads((P.parent/'pair-audit/alias-clusters.json').read_text()):
 for w in g['members']:canon[w]=g['representative']
def S(s):return set(s.split(', ')) if s else set()
def prev(c,rel):return {x['word'] for x in old if x['center']==c and x['score']==2 and x['relation']==rel}&universe
D={c:set() for c in new};B={c:set() for c in new};X={c:set() for c in new}
meanings={
'состояние':'Текущее психическое или психофизическое состояние человека. Не положение дел, не имущество, не постоянная черта личности.',
'отношение':'Субъективное эмоционально-оценочное отношение к кому-либо или чему-либо. Не связь между любыми объектами и не любые социальные отношения.',
'реакция':'Эмоциональный или выразительный ответ человека на воздействие. Не химическая реакция, не политическое значение и не любое последующее событие.',
'выражение':'Внешнее выражение переживания: жест, голосовая или телесная форма. Не словесный оборот и не математическое выражение.',
'желание':'Внутреннее стремление к чему-либо или к осуществлению чего-либо. Не любая потребность, намерение либо положительное чувство.'}
# Explicit assignments; inherited forms retain the earlier meanings.
attitudes=S('любовь, обожание, симпатия, приязнь, расположение, благосклонность, привязанность, близость, сочувствие, сострадание, жалость, сопереживание, благодарность, признательность, уважение, почтение, благоговение, преклонение, доверие, недоверие, ненависть, неприязнь, антипатия, нелюбовь, враждебность, презрение, пренебрежение')
D['состояние']=(prev('переживание','форма/содержание')-attitudes)|prev('настроение','форма/содержание')|S('напряжение, расслабление, бодрость, усталость, истощение, вялость, разбитость, комфорт, дискомфорт, бессилие, беспомощность, уверенность, неуверенность, защищённость, уязвимость, аффект, фрустрация, эйфория, дисфория, стресс, дистресс, оцепенение, возбуждение, истома, апатия, отрешённость')
B['состояние']=attitudes|S('смелость, бесстрашие, трусость, осторожность, самообладание, выдержка, терпение, невозмутимость, хладнокровие, тревожность, раздражительность, выгорание, ангедония, амбивалентность, голод, жажда')
X['состояние']=S('улыбка, смех, плач, слёзы, рыдание, всхлип, крик, вздох, дрожь, румянец')
D['отношение']=attitudes|S('влюблённость, нежность, самоуважение, гордость, ревность, зависть, отвращение, омерзение, брезгливость, интерес, заинтересованность, безразличие, равнодушие, доброжелательность, дружелюбие, высокомерие, надменность, холодность, теплота')
# These communicate or enact an attitude, not just anything that can be felt.
X['отношение']=S('одобрение, осуждение, признание, отвержение, забота, поддержка, ласка, объятие, поцелуй')
B['отношение']=S('дружба, взаимность, принятие, принадлежность, искренность, откровенность, скрытность, доброта, отзывчивость, чуткость, эмпатия, обида, злость, гнев, страх, благодарность, самодовольство, самолюбие, тщеславие, унижение, предательство')
D['реакция']=prev('эмоция','форма/содержание')-S('счастье, уныние, подавленность, угнетённость, тоска, ностальгия, безнадёжность, отчаяние, горе, скука, энтузиазм, увлечённость, томление, сопереживание, жалость, сострадание, сочувствие')
D['реакция'] |= S('оторопь, оцепенение, потрясение, обескураженность, конфуз')
X['реакция']=S('улыбка, смех, плач, слёзы, рыдание, всхлип, крик, вздох, дрожь, румянец')
B['реакция']=S('горе, тоска, ностальгия, уныние, подавленность, угнетённость, отчаяние, ненависть, любовь, обожание, влюблённость, доверие, недоверие, стыд, вина, одобрение, осуждение, поддержка, забота, принятие, отвержение, апатия, отрешённость, стресс, дистресс, фрустрация, одиночество, безутешность, выгорание')
D['выражение']=S('улыбка, смех, плач, слёзы, рыдание, всхлип, крик, вздох, дрожь, румянец, объятие, поцелуй, ласка')
B['выражение']=S('откровенность, искренность, скрытность, сдержанность, холодность, теплота, забота, поддержка, признание, одобрение, осуждение, принятие, отвержение, утешение, самообладание, выдержка, невозмутимость, хладнокровие')
# Content that could be expressed is not itself a form of expression.
B['выражение']|={x['word'] for x in src if x['layer']=='Ядро'}
D['желание']=S('стремление, влечение, вожделение, похоть, жажда')
B['желание']=S('страсть, потребность, намерение, мотивация, интерес, любопытство, увлечённость, предвкушение, надежда, ожидание, нетерпение, томление, голод, любовь, влюблённость, зависть, ревность, тоска, ностальгия, тщеславие, азарт, энтузиазм')
for c in new:
 assert (D[c]|B[c]|X[c])<=set(by)
 D[c]&=universe;X[c]&=universe;B[c]=(B[c]&universe)-(D[c]|X[c])
rows=[]
for c in new:
 for n in sorted(universe):
  if n in D[c]:grade=2;rel='форма/содержание';reason=f'«{n}» рассматривается как непосредственная форма или содержание центра «{c}» в фиксированном значении.'
  elif n in X[c]:grade=2;rel='выражение';reason=f'«{n}» — обычное проявление или способ выразить {c}. Это не однозначный диагностический признак.'
  elif n in B[c]:grade=1;rel='пограничное';reason=f'Для «{n}» связь с «{c}» требует контекста, иного значения или другого отношения. В прямой охват не включена.'
  else:grade=0;rel='нет прямого охвата';reason=f'«{n}» не является принятой здесь прямой формой или выражением центра «{c}». Другие возможные связи не отрицались и не подсчитывались.'
  rows.append({'center':c,'word':n,'representative':canon[n],'grade':grade,'relation':rel,'explanation':reason})
assert len(rows)==1520
oldsets={c:{canon[x['word']] for x in old if x['center']==c and x['score']==2 and x['word'] in universe} for c in old_centers}
base=set.union(*oldsets.values());sets={c:{canon[n] for n in D[c]|X[c]} for c in new}
summary=[]
for c in new:
 direct=sets[c];member={canon[n] for n in D[c]};expression={canon[n] for n in X[c]}-member
 shared=direct&base;added=direct-base
 nearest=max(old_centers,key=lambda old:len(direct&oldsets[old])/len(direct|oldsets[old]))
 summary.append({'center':c,'meaning':meanings[c],'forms':len(member),'expressions':len(expression),'direct':len(direct),'borderline':len({canon[n] for n in B[c]}-direct),'shared_with_first_five':len(shared),'new_vs_first_five':len(added),'new_words':sorted(added),'partners':sorted(direct),'closest_old':nearest,'closest_jaccard':round(len(direct&oldsets[nearest])/len(direct|oldsets[nearest]),4)})
allsets=oldsets|sets
ov=[]
for a,b in itertools.combinations(old_centers+new,2):
 inter=allsets[a]&allsets[b];union=allsets[a]|allsets[b]
 ov.append({'a':a,'b':b,'shared':len(inter),'only_a':len(allsets[a]-allsets[b]),'only_b':len(allsets[b]-allsets[a]),'jaccard':round(len(inter)/len(union),4)})
result={'universe_raw':len(universe),'universe_representatives':len({canon[n] for n in universe}),'initial_coverage':len(base),'combined_coverage':len(set.union(*allsets.values())),'new_centers':summary,'overlap':ov,'scope':'Only direct membership/content and expression. No claim of all possible pair relations.'}
(P/'coverage.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(P/'classification.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
lines=['# Проверка второй пятёрки центральных понятий','','Это исследовательское продолжение, без изменений игры. Все результаты — авторские смысловые гипотезы, не данные опроса и не научные нормы.','','## Единая база сравнения','','Из исходных 310 исключены пять прежних центров и «желание», которое теперь само является центром. Оставшиеся **304 слова** проверяются против каждого из пяти новых центров: **1 520 ячеек**. Четыре новых слова не добавлены как партнёры в исходный словник. Первая пятёрка пересчитана на той же базе. Синонимические группы сохранены из предыдущего аудита.','','Проверяются прямые формы/содержание и выражения. Возможные причины, объекты желания, свойства выражения и другие отношения не подмешиваются в основной счётчик. Поэтому «я могу выразить любое чувство» не даёт «выражению» автоматически 167 партнёров. Ноль означает невключение по ограниченному критерию, не невозможность любой связи.','','## Результаты','','| Кандидат | Форм/содержаний | Выражений | Всего прямых | Пограничных | Новых сверх первой пятёрки |','|---|---:|---:|---:|---:|---:|']
for s in summary:lines.append(f'| {s["center"]} | {s["forms"]} | {s["expressions"]} | {s["direct"]} | {s["borderline"]} | {s["new_vs_first_five"]} |')
lines+=['',f'Первая пятёрка охватывает {len(base)} представителей; все десять — {result["combined_coverage"]}. Это не вероятность хода: состав игровой колоды пока не выбран.','','## Значения, партнёры и добавленная область','']
for s in summary:lines += [f'### {s["center"]}',s['meaning'],'','Прямые партнёры: '+', '.join(s['partners'])+'.','','Новые относительно объединения первой пятёрки: '+(', '.join(s['new_words']) or 'нет')+'.','']
lines+=['## Вывод','','- **Состояние** — широкий центр, но его широта сама по себе не означает большой новый охват: многое уже входит в переживание. Может быть альтернативой или дополнительной общей картой.\n- **Отношение** выделяет направленность к людям, себе и объектам: любовь, доверие, уважение, неприязнь. Полезный отдельный ракурс, даже при пересечении с чувством.\n- **Реакция** выделяет ответ на происходящее: испуг, удивление, возмущение. Пересекается с эмоцией, но задаёт иной вопрос.\n- **Выражение** — центр внешних проявлений, а не внутреннего содержания. Новых слов по сравнению с первой пятёркой может почти не быть: первая пятёрка уже считала выражения. Это не делает роль слова бесполезной.\n- **Желание** даёт небольшой, но отдельный мотивационный участок. Не расширять его автоматически за счёт всех желаемых объектов или приятных эмоций.','','Предложение: сохранить все десять как исследовательских кандидатов, не как окончательную центральную колоду. Для различимых стартов прежде всего рассмотреть отношение, реакцию и выражение. Состояние сравнить с переживанием; желание проверить вместе с дополнительным словником мотивации. Число новых слов — диагностическая метрика, не новый обязательный критерий пользователя.','','## Спорные места','','«Состояние» могло бы включать почти любое переживание при широком употреблении. Здесь устойчивые отношения и качества вынесены в пограничные. «Жажда» засчитана для желания только в переносном значении из исходного словника; телесная жажда не подменяет его. «Признание» для отношения — признание заслуг, а не признание в любви. «Выражение» зафиксировано как внешняя форма; признаки вроде искренности и содержание вроде радости отмечены пограничными для данного ограниченного счёта.','','## Источники и происхождение чисел','','Значения уточнялись по доступным индексированным выдержкам словарей Грамоты. Источники не подтверждают наши индивидуальные пары или цифры.','', '- [Желание](https://gramota.ru/poisk?mode=all&query=желание): внутреннее стремление к чему-либо.\n- [Выражение](https://gramota.ru/poisk?mode=slovari&query=Выражение): передача содержания словами или другими средствами.\n- [Ответ](https://gramota.ru/poisk?mode=all&query=Ответ): ответное действие или отклик; косвенное основание для значения реакции.','', '[Состояние — метасловарь Грамоты](https://gramota.ru/meta/sostoyanie) описывает внутреннее самочувствие и расположение духа. Для отношения здесь явно задано эмоционально-оценочное рабочее значение; оно не выдаётся за дословное словарное определение.','','## Проверяемость','','- [Матрица 304 × 5](matrix.md).\n- [Все ячейки с пояснениями](classification.json).\n- [Покрытие и пересечения всех десяти центров](coverage.json).\n- [Исходные наборы и воспроизводимый расчёт](build.py).']
(P/'README.md').write_text('\n'.join(lines)+'\n')
lookup={(r['word'],r['center']):r['grade'] for r in rows}
lines=['# Матрица новых центров','','2 — прямой охват/выражение; 1 — погранично; 0 — не включено по этому критерию.','','| Слово | Состояние | Отношение | Реакция | Выражение | Желание |','|---|---:|---:|---:|---:|---:|']
for w in sorted(universe):lines.append('| '+w+' | '+' | '.join(str(lookup[w,c]) for c in new)+' |')
(P/'matrix.md').write_text('\n'.join(lines)+'\n')
for s in summary:print(s['center'],s['direct'],'new',s['new_vs_first_five'],s['new_words'])
print('coverage',len(base),result['combined_coverage'])
